def _act(x, name):
    if name in (None, "NONE"):
        return x
    if name == "RELU":
        return jnp.maximum(x, jnp.zeros((), x.dtype))
    if name == "RELU6":
        return jnp.clip(x, jnp.zeros((), x.dtype), jnp.full((), 6, x.dtype))
    if name == "RELU_N1_TO_1":
        return jnp.clip(x, jnp.full((), -1, x.dtype), jnp.ones((), x.dtype))
    if name == "TANH":
        return jnp.tanh(x)
